quests[89677] = { id = 89677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: The Emerald Nightmare, Normal", description = "Some challenges cannot be faced alone. While numbers do matter, good teamwork is even more potent.\n\nGather your most trusted allies to help you conquer this incarnation of Emerald Nightmare.", progress = "You should assemble a team you can trust before taking on this challenge, {name}.", completion = "Teamwork makes the dream work, or so they say. It would appear that the rhyme carries truth to it. Hmmm.\n\n<Eternus pauses for a moment in thought.>\n\nI wonder what other rhymes carry such power. That bears some future experimentation.", objectives = "Defeat 2 bosses in The Emerald Nightmare on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89678] = { id = 89678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Time to Raid, Arcing Aqueducts", description = "We require information about how multiple timerunners and their artifacts interact when faced with powerful opposition.\n\nSeek out others to help you conquer Arcing Aqueducts.", completion = "The sum strength of a group of timerunners armed with potent artifacts is greater than that of the individuals. Much greater than anticipated. Intriguing.", objectives = "Complete the Arcing Aqueducts wing of The Nighthold on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
