quests[89683] = { id = 89683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Time to Raid, Royal Athenaeum", description = "We require information about how multiple timerunners and their artifacts interact when faced with powerful opposition.\n\nSeek out others to help you conquer Royal Athenaeum.", completion = "The sum strength of a group of timerunners armed with potent artifacts is greater than that of the individuals. Much greater than anticipated. Intriguing.", objectives = "Complete the Royal Athenaeum wing of The Nighthold on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90081] = { id = 90081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Runed Sigil", description = "An Arcane Runed Sigil is essential in proving an item's authenticity as a true masterpiece of Azure artisans. Of course, they can be affixed to any object, turning a flea market trinket into something that appears to be a priceless work of art.\n\nI could create something like that, and it might turn a great profit. If you travel to the Azure Vault and gather the parts I need, we can use them to craft a Sigil.\n\nBring me enough parts for two, and I shall keep one as my fee for the service.", progress = "Have you collected the parts?", completion = "Excellent, this is more than enough to construct what you require.", objectives = "Enter the Archival Assault delve and collect 24 Etched Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90093] = { id = 90093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey Contract: Murloc Shadowhunter", description = "A MURLOC SHADOWHUNTER has been spotted in Zul Aman!\n\nDifficulty: Hard\n\nAffixes: Mark of the Prey\n\nYour target will occasionally mark you, decreasing your damage done and increasing damage taken." }
quests[90094] = { id = 90094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo of the Hunt", description = "Haranir are fierce and ferocious--cunning and canny. In time, we became the most feared beasts upon the mountain.\n\nA great many wise and powerful beasts roamed the hills of our old mountain. But in time, we came to master them all.\n\nToday, you shall hunt as we once did.", completion = "You have proven yourself a capable hunter like our ancestors of old. But simply being the strongest did not prove succor enough for the minds of our people.", objectives = "Complete the second trial at the Den of Echoes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90095] = { id = 90095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo of the Call", description = "When the haranir began to grow restless, they looked to new sources of purpose. Some cast their gazes upward, toward the stars and the moon. Others, such as the Hara'ti, heard a call from deep within the world.\n\nThe moment the first of the Hara'ti heard the Song echoing from the roots, we knew that we had found a new purpose. We would seek out the source of the Song, and discover the truth of it for ourselves.\n\nBut it would be a difficult road. Strange stone monsters sought to block our path.", completion = "Now you know how the Hara'ti came to walk amongst the roots.\n\nOne final trial remains--the most difficult, but most important, of them all.\n\nHagar awaits you, and will guide you through the next challenge.", objectives = "Complete the third trial at the Den of Echoes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90096] = { id = 90096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Worldly Deeds", description = "All across the Broken Isles there are people in need. They search for hope but are hard pressed to find any. You can be that hope.\n\nSeek out those in peril in the Broken Isles and be the champion they so desperately need.\n\nIt is through such acts that legends are made.", progress = "Somewhere, someone is in need. All they need is a champion to save them.", completion = "A single heroic act can turn the tide. A single whisper of hope can turn back despair. This is what gives legends their power.", objectives = "Complete 4 world quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90097] = { id = 90097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Invasion Points", description = "The Legion does not fight conventionally. They deceive, manipulate, and undermine their opposition at every turn.\n\nThere are no battle lines against the Legion. They will open rifts at a weak point and then spill out of it sowing death and destruction. When they invade, it is on their terms.\n\nHowever, this strategy is not invincible. Potent champions, able to move and react swiftly, can stop these invasions at their source. Stop the Legion Invasion. Show people that the Legion can be defeated.", completion = "The power you and your artifact possess were able to halt a Legion invasion. But was it you, or the artifact you wield, that is responsible? On that I will require more information.", objectives = "Complete a Legion invasion point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90098] = { id = 90098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Greater Invasion Points", description = "Once the Legion has sown confusion and chaos, then they will begin their real assault. Huge invasion rifts will open and the Legion will march forth in great numbers. The defenders, scattered to protect against smaller rifts, will lack sufficient strength anywhere to stop them.\n\nThat is when champions like you are most needed.\n\nSeek out one of the Legion's major invasions and throw everything you have at it. \n\nShow the people that with enough determination you can cancel the apocalypse.", completion = "Just as I predicted. You were able to stop a massive Legion invasion. It was not you, or your artifact that did this. Rather it was the combination of both that won the day.", objectives = "Complete a greater Legion invasion point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90099] = { id = 90099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Combat Studies, Rare", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare study, so focus on fighting rare opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 6 rare enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90100] = { id = 90100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Combat Studies, Rare Elites", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare elite study, so focus on fighting rare elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 2 rare elite enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90101] = { id = 90101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Terrors of the Broken Isles", description = "It is time to put both you and your artifact to the test.\n\nSeek out a Terror of the Broken Isles and defeat them.\n\nI am certain that, no matter the outcome, you will provide us with much to think about. I will be watching with great interest.", progress = "How fares the research?", completion = "A fascinating outcome, {name}. This will shed some much needed light on our research.", objectives = "Kill a world boss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90102] = { id = 90102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Champion of the Broken Isles", description = "Our research suggests that power is only part of the equation--what one does with it is also of great importance.\n\nThe people of the Broken Isles need a champion. Come to their aid and drive the Legion from their shores and your legend will grow.\n\nWhere you choose to start is up to you--the Legion is everywhere, so one place is just as good as another.", completion = "Your legend has grown, {name}. The timeline reverberates with not just the substance of your deeds, but it compounds as it impacts those around you. This has been a most fruitful addition to our research.", objectives = "Complete any Legion zone campaign chapter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90103] = { id = 90103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Champion of the Order Hall", completion = "You have gained the respect due to a true {class}. You are a leader. All that remains to be answered is where you are going.", objectives = "Complete a chapter of your Order Hall campaign.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90108] = { id = 90108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Artifact Collector", description = "As we study this timeline and your effect upon it, a question has been raised--what would be different if you had a different artifact?\n\nSeek out a new artifact and let us see whether the first choice you made was good, or great.", completion = "You have quite the collection now, {name}. All that remains to be seen is whether you prefer one artifact over the other.", objectives = "Acquire a new artifact weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90109] = { id = 90109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Clear the Skies", description = "Manipulating time is not without its risks or its rewards.\n\nThe strain on this timeline has produced numerous residual time motes through the Broken Isles. It would be irresponsible not to clean them up.\n\nHowever, there is opportunity here. If you were to gather these motes, then their latent infinite power would be bestowed upon you instead.\n\nWe can clean up the timeline and enhance our research at the same time.", progress = "This timeline is pockmarked with time motes. Gather as many as you can.", completion = "Good. Nothing dramatic occured when you gathered the residual time motes. If you start to feel anything strange, do let us know though.", objectives = "Collect 50 residual time motes while flying.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90110] = { id = 90110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Gather Timewarped Samples", description = "The fraying of this timeline has had some interesting effects on plants and stone. We would like to study them.\n\nGather samples of timewarped herbs and ores from around the Broken Isles and being them back for analysis.", progress = "How fares the research?", completion = "Moratari will be elated to see so many test samples. Thank you for your diligence.", objectives = "Gather timewarped herbs and ores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90111] = { id = 90111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Combat Studies, Demonology", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a demonology study, so focus on fighting demonic opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 75 demons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90112] = { id = 90112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Combat Studies, Elite", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be an elite study, so focus on fighting elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, {name}. Moratari will be overjoyed to see these new data points.", objectives = "Kill 25 elite enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90113] = { id = 90113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Self Improvement, Basic", description = "By improving yourself we can compare your power to that of your artifact. Only then will we be able to determine if it is the artifact, or its wielder, that is most important.\n\nGo forth and grow stronger, more focused, more experienced--then return to me so we may record your improvements.\n\nThe road to self improvement is a long one, so pace yourself.", progress = "Remember to pace yourself, the journey is just as important as the destination.", completion = "Impressive. I can sense your power. This is a most critical addition to our research.", objectives = "Complete various activities on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90114] = { id = 90114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Self Improvement, Advanced", description = "By improving yourself we can compare your power to that of your artifact. Only then will we be able to determine if it is the artifact, or its wielder, that is most important.\n\nGo forth and grow stronger, more focused, more experienced--then return to me so we may record your improvements.\n\nThe road to self improvement is a long one, so pace yourself.", completion = "Impressive. I can sense your power. This is a most critical addition to our research.", objectives = "Complete various activities in Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90115] = { id = 90115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Combat Studies, Groverunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of your attunement to the forest, so focus on fighting opponents using the power of nature.\n\nAnd remember, this is for the greater good.", completion = "Impressive. I can sense your power. This is a most critical addition to our research.", objectives = "Kill 100 enemies while Call of the Forest is your active artifact ability.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90119] = { id = 90119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "test" }
quests[90122] = { id = 90122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate Xy'vox the Twisted", description = "<Use the Xy'vox Refuge Dampener to reveal and eliminate Xy'vox the Twisted.>", progress = "Eliminate Xy'vox the Twisted.", completion = "Excellent work, I will issue a reward for eliminating this warrant target." }
