quests[90127] = { id = 90127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate Arcana-Monger So'zer", description = "<Use the Arcane Lure to reveal and eliminate Arcana-Monger So'zer.>", progress = "Eliminate Arcana-Monger So'zer.", completion = "Excellent work, I will issue a reward for eliminating this warrant target." }
quests[90128] = { id = 90128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miscreant Baras!" }
quests[90467] = { id = 90467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tales of the Sky", description = "Wait a minute... You're no rutaani at all! Are you one of those \"outsiders\" that Saku and Orkon keep talking about?\n\nOh! I just had a great idea. Did you know that the Goddess used to have a pet? Rumor has it that when the Goddess disappeared, Aln'sharan was SO sad that he flew up into the highest roots of Harandar, never to be seen again. But every so often, he goes looking for food... And his scales fall as skyglass!\n\nI wanna gather some. It's my dream to see Aln'sharan firsthand! Will you help me?", progress = "Aln'sharan is a folk tale that we tell haranir children to explain the shards of glass that occasionally rain upon Harandar.\n\nMost grow out of searching for sky serpents. But Kuri's heart has always been filled with whimsy.", completion = "Goddess preserve. Kuri has always had her mind wrapped up in the roots.", objectives = "Collect 6 Stray Skyshards in the Cascades of Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90468] = { id = 90468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ugh, Chores!", description = "Okay, so I may have a DIFFERENT thing that I'm supposed to be doing in the Cascades, too. It's my turn to gather saptor fronds for stew. It's such a pain. Not only are saptor fronds horribly bitter, but the saptors are barely even fun to hunt! They don't even make your blood flow that fast before they die.\n\nBut hey! You probably don't get to fight saptors as often as I do. Maybe while you're looking for skyglass, you could gather some up for me? You know... while you're in the area.", progress = "Oh, Kuri...", completion = "Kuri is as imaginative as she is fierce, but she also has a bad habit of neglecting her chores. I appreciate your contribution to our community, though I shall have to give Kuri a scolding once she returns.", objectives = "Collect 8 Intact Saptor Fronds from the saptors of the Harandar Cascades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90469] = { id = 90469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carry On, Wayward Kuri", description = "Oh, that Kuri. She holds tightly to our ancient traditions and tales... perhaps too tightly.\n\nThere is a difference between holding reverence for our ancient ways and chasing them into dangerous caves. I fear she might bite off more than she can chew in her search for Aln'sharan.\n\nWon't you go after her? She seems to trust you, now that she sees you as her co-conspirator in this quest. Please bring her home safely.", completion = "O-Okay... so maybe I'm a bit afraid of the dark. But that doesn't mean I'm not going in there!\n\nYou'll be there with me too, right? There are probably tons of skyshards to be found inside!", objectives = "Find Kuri in Dreth'amar Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90470] = { id = 90470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skyglass Scavenging", description = "The adults find all sorts of stuff in the caves around here that we use back at the village. A lot of the critters that live in the caves like to gather skyglass, in particular. I guess they think it's shiny.\n\nThat's good for us, though! It means we can go and get a bunch of skyglass. Go in there and make sure the coast is clear, and then I'll come in and gather up as much as I can carry!\n\nAt this rate, we'll be able to summon Aln'sharan in no time.", progress = "Come onnn! We've gotta hurry before mom gets TOO worried.", completion = "Yes! Yes, yes, yes! This is soooo much!\n\nAln'sharan will notice for sure. He probably wants all of his skyglass back!", objectives = "Gather as much Skyglass as Kuri can carry from Dreth'amar Cavern in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90474] = { id = 90474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Aln'sharan", description = "This is it! We have all the skyglass we can carry.\n\nThe legends say that Aln'sharan cries crystal tears to mourn the missing Goddess. Maybe if we give the crystals back to him, he won't be so sad? Maybe then he'll appear for us!\n\nMeet me back at the village. I think I know the perfect place to make our offering.", progress = "Come on! We don't wanna miss our chance! Also all of this skyglass is heavy. Can't you carry some?!", completion = "You know... I thought I would be sad if this didn't work, but I actually feel okay!\n\nI still believe. There's so much magic in the world. And even if Aln'sharan isn't exactly what I think he is... his story still exists for a reason. And that's important to me, I think.", objectives = "Return to Kuri in Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90481] = { id = 90481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Have a Permit", description = "These Witherbark youths are telling us we can't stay here.\n\nBut I've been talking to one of their elders for months to be sure we'd have permission to set up camp and explore. I even have copies of all the letters!\n\nCan you find Elder Ren'zen in Witherbark Village and show him his letter of approval?", progress = "Elder Ren'zen seemed so pleasant in his letters. Why all the hostility now?", completion = "He confirmed what he'd sent was a letter of approval? Good! I'm glad that's cleared up.\n\nMaybe now we can get a more pleasant introduction to Zul'Aman.", objectives = "Find Elder Ren'zen in Witherbark Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90482] = { id = 90482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cuisine Connection", description = "Dis \"seeker\" has been askin' a lot of questions about de foods we eat.\n\nIt sounds like these tortollans like to eat poisonous foods. De Witherbark do as well. There are many foods we eat that could kill us if not treated properly.\n\nGo collect zapgut eel stomachs and blisterskin kelp. I'd like to test dis turtle's tongue.", progress = "We ingest some poisons to make ourselves resistant to potential threats.\n\nSome just taste good or provide a good thrill.", completion = "Excellent. Now to prepare it.", objectives = "Collect 6 Zapgut Eel Stomachs and 60 Blisterskin Kelp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90483] = { id = 90483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Witherbark Story", description = "The Witherbark say they have a lot of stories to tell, but I've heard two and BOTH involved a sparring match!\n\nPlease, can you ask the Witherbark here for stories? My old bones can't take another reenactment!", progress = "What's wrong with a gentle story about falling asleep at an inopportune time?\n\nTortollan folklore is full of those. Do trolls not sleep?", completion = "I see. They keep clear records of all these battles at least. Their storytelling is quite strenuous!", objectives = "\"Reenact\" 5 Witherbark stories in Camp Stonewash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90484] = { id = 90484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sightseeing Stegadon", description = "Wow, your armor is sooooo cool!\n\n<Trishe stares, slack-jawed.>\n\nOh, have you seen my friend Steggy? She was here with me, but then there were all these pretty bugs and things, and she ran off after them, and I was too slow to follow her.\n\n<Trishe pouts.>\n\nI'm s'posed to watch Steggy. I'm response-able! And now you're response-able for finding her, okay?", progress = "Have you seen how big the trolls are? Steggy is going to be bigger than the trolls, but she's still little like me.\n\nSteggy needs to eat so she can get bigger. Please find her so I can feed her!", completion = "Steggy is back! You really are response-able.", objectives = "Find Steggy and defeat Hidegorger the Everburning in Zul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90485] = { id = 90485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Afterthought Artifacts", description = "This location is ideal for finding artifacts. Searching through the rubble at the bottom of that lake could reveal many treasures.\n\nIf you have a moment, you're welcome to take a look around yourself. Bring me anything you find and we'll see if it's valuable.", progress = "Found anything exciting yet?", completion = "My my, what an interesting find!\n\nThere's a lot to be learned from an old pot: how the ancient Amani might have prepared food, the kinds of food they ate, and what they valued most in a meal.\n\nI'll work on analyzing this. You can place those other items to the side. They're far younger than this beauty.", objectives = "Find artifacts in the lake near Camp Stonewash in Zul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90486] = { id = 90486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Delicacies", description = "A Witherbark troll could survive eatin' each of these ingredients raw, but dey would need aid.\n\nTogether, de ingredients would be deadly. We're going to cook dem into one dish.\n\nDon't worry. I'll show you how to take out enough poison so it tastes good AND has paralytic effects.", progress = "What do you think this is going to taste like? Amaxi says it's absolutely arresting and could kill a stegodon!", completion = "I suppose now we try it. Right, {name}?", objectives = "Cook Blistereel Boar in Camp Stonewash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90493] = { id = 90493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of Tranquillien", description = "We can't let the Twilight's Blade get away with this. There are innocent citizens all over town who had nothing to do with this cult. You heard the governor: anyone who doesn't join will be executed.\n\nI won't stand for that.\n\nGo--aid any civilians you can find. Get them out of harm's way. If they're being attacked, take their attacker down. Tranquillien will not fall under my watch.", completion = "You're safe, and so are the weary citizens of Tranquillien. Thank the Light.", objectives = "Rescue 8 innocent Tranquillien Citizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90494] = { id = 90494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Magister", description = "Umbric went to chase down Antenorian when the fighting broke out, but nobody has seen him since. \n\nI trust him to hold his own, but between Kasiea's death and Antenorian's betrayal, I worry he may be so set on revenge that he won't see an attack if one happens. Can you find him for me?\n\nI'll stay here and make sure these civilians remain safe.", progress = "I will not allow them to get away with this.", completion = "A map of Eversong? With multiple villages marked by the Twilight's Blade!", objectives = "Find Magister Umbric.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90509] = { id = 90509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traitors of Tranquillien", description = "Some of the town's most respected citizens, traitors?\n\nHow long has the Twilight's Blade been here? How many scouts have gone missing? Crimes gone unreported? Innocents recruited by those they thought they could trust?\n\nThey must be stopped. Cut down the traitors. Show them that Tranquillien is no home for cultists.", progress = "We cannot allow these traitors to escape!", completion = "We'll need to do more to reverse the damage done here, but this was a good first step. Thank you.", objectives = "Slay Ranger Lethvalin, Matron Narsilla, and Guard Captain Leonic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90517] = { id = 90517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Part of the Deal", description = "The threat of the Shadowguard to Eco-Dome: Primus is over. My Reshii Ribbon is no longer needed to protect this asset. Take it. Use it wisely. Protect the greatest investment of all--our existence.\n\nStay focused! The Harbinger has already driven off one member of your team. Once you get enough Reshii Ribbons, you still need to fight Dimensius. Find allies who will stand with us, in addition to artifacts.", progress = "The Reshii Ribbons are a means to get you and your allies to Dimensius. You will need at least two more if this plan is going to work.", completion = "You have my ribbon. Go--track down the rest. Have Locus-Walker contact the other members of the Ravel. Ask the Harbinger if she knows any ancient horrors that have acquired one. Remember rule twelve--it's who you know.", objectives = "Take Ve'nari's Reshii Ribbon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90533] = { id = 90533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Get Orweyna!", description = "Hey! Champ!\n\nLook, I swear I'm glad to see ya. I'm just in a little bit of a diplomatic situation here.\n\nCan you go get Orweyna and bring her back here? See if she'll talk this beast into letting me go?\n\nI'm not an elekk plushie, for cryin' out loud.", progress = "Never try to take something from a beast like this without offering something better. \n\nI would hate to lose another friend that way.", completion = "I'm pleased that Monte came this way to visit. But I can see that he is as out of his depth here as I was in Undermine.", objectives = "Go get Orweyna in the Den and find a way to free Gazlowe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90534] = { id = 90534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Home of the Haranir", description = "I am eager to show Monte my home, but I know it is very different from what he is used to.\n\nCome with us as he meets my people.", completion = "Can't say I've ever seen a place like this before. But I like it. I can see how the haranir were drawn here. How Orweyna grew up here and learned all she learned.\n\nBah, look at me getting sentimental. What's next?", objectives = "Accompany Orweyna and Gazlowe around the Cradle and the Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90535] = { id = 90535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Your Mark", description = "One thing that is very important to the haranir is our past. Some may remove their ability to hear the Goddess, but we are all connected to who came before us.\n\nYou and Gazlowe are a part of our history now. You have earned the right to leave your mark here in the Den, for as long as the Den remains.\n\nGo, touch the wall with your painted hand, and know that you touch the same stone as generations before you.", progress = "We are continually making ourselves new, even as we hold to what came before. I should remember this more often.", completion = "There. Now you are part of Harandar.", objectives = "Paint your mark on the wall of the Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90536] = { id = 90536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tale of Wey'nan's Ward" }
quests[90537] = { id = 90537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Late Bloomers", description = "It is good to see you again, {name}. Orweyna told me that you might be able to help me with something.\n\nA group of rutaani were due to arrive here earlier today, but they're late. They're coming up from Blooming Terrace with my mentor, Ru'gar, and I am worried they've had trouble on the road.\n\nWill you scout along the road from here down to the Terrace? I'll come up from there and we can meet on the way if we find nothing.", progress = "Quietly now. The enemy is close.", completion = "Welcome to Fungal Cleft, {name}. The local fungarians here are more volatile than those at Har'mara.\n\nThey have no concept of balance and strive to spread their spores far and wide, overcrowding the nearby rutaani of Blooming Terrace and threatening to spill out into the rest of Harandar.\n\nThe captured rutaani must be within the settlement.", objectives = "Look for the missing company of rutaani and haranir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90538] = { id = 90538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey Contract: Zealous Crusader", description = "A ZEALOUS CRUSADER has been spotted in Eversong!\n\nDifficulty: Hard\n\nAffixes: Grounded!\n\nUnable to use mounts while inside your active Prey Area." }
quests[90540] = { id = 90540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rutaani Rescue", description = "Over the hill north of here is a fungarian village, Fungal Cleft. I believe the missing rutaani have been taken there.\n\nThe fate that awaits them is a brutal one if we do not get them back quickly. Usually, fungarians favor hosts that are already dead for their reproductive purposes. The ones here are strangely vicious, however. I have seen some mushroom-covered animals and rutaani who are still moving around! It is unnatural.\n\nGo to Fungal Cleft and see if you can rescue the missing travelers.", completion = "Good work, {name}. I saw the freed rutaani rushing toward Har'mara.\n\nThese fungarians were in pursuit, but I got the jump on them.", objectives = "Rescue 5 Captured Rutaani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90544] = { id = 90544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thief at Bark", description = "<Luma stands in front of you, ears perked, thankful for your help.\n\nShe lets out a short bark, tail wagging once before trotting a few steps forward, then pausing.\n\nGlancing back, Luma waits expectantly. Her body language pleads, \"Come on, follow me!\">", progress = "<Luma appears to be waiting for your approval.>", completion = "<Luma nudges a small reward into your hand, as if in appreciation for your help.\n\nPerhaps there is no reason to be concerned over the amount of stolen items in the treasure pile after all.>", objectives = "Follow Luma.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90545] = { id = 90545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Reel Problem", description = "An essential component of the Oasis ecosystem is the aquatic life within our small lake. \n\nIt appears that artificial organisms known as Hyrobites are in the lake. Originally introduced to remove toxins in the water, their continued presence threatens the equilibrium of the water.\n\nPlease remove these mechanical fish immediately!", progress = "Did you catch those fish?", completion = "Fine work. I am most pleased to not have to handle those nasty fish myself.", objectives = "Catch 7 Hydrobites around the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90546] = { id = 90546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Paladins", description = "Some of our brothers and sisters in the Light were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area.\n\nWe expected to hear back from them awhile ago, but we've heard nothing.\n\nGiven the strength of the party that went, Salandria and I wanted some additional backup before we looked into the issue. Care to lend a hand?", completion = "Well, the cultists don't seem to be hiding now. But I don't see any of our missing paladins.", objectives = "Meet Taelia at the Sanctum of the Moon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90547] = { id = 90547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Paladins", description = "Some of our brothers and sisters in the Light--including my friend Dawnheart--were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area.\n\nWe expected to hear back from them awhile ago, but we've heard nothing.\n\nGiven the strength of the party that went, Taelia and I wanted some additional backup before we looked into the issue. Care to lend a hand?", completion = "The cultists are boldly showing themselves, but I don't see Dawnheart and the others.", objectives = "Meet Salandria at the Sanctum of the Moon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90548] = { id = 90548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Missive", description = "We need to figure out what the Twilight's Blade is trying to do here. We also need to get rid of these cultists so the Magisters can get back to their work building runestones.\n\nTake out as many cultists as you can. See if any of them are carrying information we can use.", progress = "What'd you find?", completion = "Good job out there. We'll need to find more if we're going to find our missing friends.", objectives = "Collect 6 missives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90549] = { id = 90549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of the Struggle", description = "The Twilight's Blade are acting boldly in their takeover here. None of these Magisters have any information for us.\n\nWe'll hold this end of the bridge and protect any Magisters who escape. You get in there and look for signs of the missing paladins. Were they taken? Did they put up a fight, or were they ambushed? Are they still armed?\n\nI have a bad feeling we are running out of time.", completion = "Well, we know more. They were here at one point but they've been taken, unarmed. Now we need to find out where to.", objectives = "Look for signs of the lost paladins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90550] = { id = 90550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Somber Sun", description = "<The corpse of this Blood Knight has been horribly mangled and tainted by Void magic. He put up a fight, but was unable to survive.\n\nSalandria will want to know of this.>", completion = "Those bastards... They'll pay for Sombersun's death!", objectives = "Report the corpse to Salandria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90551] = { id = 90551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captured Information", description = "We need to find out where the paladins were taken. Easiest way to do that is ask... under a bit of duress.\n\nFind an isolated target, beat them down, and then drag them to the hollow on the other side of the Sanctum. Taelia and I will get the civilians to safety and meet you there.", progress = "Did you capture a cultist?", completion = "Good. Now we can force some answers.", objectives = "Capture and bring an isolated cultist to the Hollow Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90552] = { id = 90552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interrogation", description = "We need to know where Dawnheart and the others were taken. This one doesn't seem to want to talk... but we can fix that.", completion = "The Ruins of Deatholme. They better be alive when we get there!", objectives = "Interrogate the captive cultist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90553] = { id = 90553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executing the Blades", description = "Those monsters will pay for what they have done!\n\nTake out any Twilight's Blade cultists you see. We'll scour them from Eversong for good!", progress = "Show them no mercy!", completion = "We have wiped Eversong clean of their filth.", objectives = "Kill 15 cultists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90554] = { id = 90554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Ashes in Your Wake", description = "We need to make it clear to these cultists that they aren't welcome.\n\nTear down their banners, and destroy their books and supplies. Do whatever you can to wreck their camp!", progress = "Have you destroyed the camp?", completion = "Good work. Even if they come crawling back, they won't find much.", objectives = "Wreck the Twilight's Blade camp in Deatholme.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90555] = { id = 90555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Freedom", description = "Our friends are being held in this area. I have no idea what state we'll find them in, but I pray they are at least alive.\n\nHelp me find and free our missing paladins in the Ruins of Deatholme.", progress = "Have we found everyone yet?", completion = "All things considered, this was a good result. I wish... well. We couldn't save everyone, but we did save most of them. I guess that's as much as anyone can ask for in a situation like this.", objectives = "Free paladins in the Ruins of Deatholme.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90556] = { id = 90556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting off the Head", description = "We'll crush their leader! For justice and the Light!", progress = "May their ilk never come around here again!", completion = "We'll mourn the lost and celebrate those who survived. Thank you, {name}.", objectives = "Slay Overseer Mognak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90557] = { id = 90557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whose Key is This?", objectives = "Hey pal, we found a weird key lying around. No idea who it belongs to, it ain't for the Incontinental. You want it?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90568] = { id = 90568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlikely Friends", description = "This old Witherbark pot you found is quite interesting.\n\nI've made a series of notes on its construction and use, but now it's time we speak to Elder Ren'zen. The pot should be returned to him. And he can fill in the gaps in the pot's story!\n\nLet's speak with him in the village.", completion = "Seeker Crikkash says he wanted to wait for you to arrive before showing me what he's found.", objectives = "Speak with Elder Ren'zen in Witherbark Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90569] = { id = 90569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in the Bag", description = "What a mess this is. The sack you found was supposed to be filled with seeds. They're part of an important cultivation project that Ru'gar was working on.\n\nIt appears the fungarians made off with the seeds when they captured the rutaani.\n\nWhile you're looking for the rutaani, see if you can recover the seeds that were stolen.", progress = "I can't bear to think of what the fungarians will do to the seeds that Ru'gar has been carefully cultivating. He had been working with the rutaani on plants that were more hardy and produced greater yield. \n\nHis work should not be lost.", completion = "You found so many! Thank you.\n\nThese seeds were very important to Ru'gar. I don't know much about gardening, but maybe I can give it a try.", objectives = "Collect 6 Stolen Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90570] = { id = 90570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Ruins of Deatholme", description = "Thanks to our \"friend\" here, we know the missing paladins were taken to Deatholme. We have to find them before it's too late! \n\nSalandria and I will meet you there.", completion = "Good--you made it. Now let's save those paladins.", objectives = "Meet Taelia and Salandria at Deatholme.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90571] = { id = 90571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lay of the Beast", description = "Your friend's scheme to blow up the Nexus-Point was adorable. You all looked so determined, I didn't have the heart to tell you how simple the solution really is.\n\nThe Mantle of Predation will allow you to enter the Nexus-Points and weaken the storm. Alas, it's claiming the Mantle that will truly test you.\n\nBorrow my pet--see through his eyes. I'll show you who you'll steal the Mantle from.", progress = "Go on. Ciphus won't mind.", completion = "There you have it--simply steal the Mantle from Terminas. I'd recommend acting quickly. Who knows when Terminas will return to the Obscurion Citadel.\n\nA shame about Ciphus. I was planning to devour him myself once I'd fattened him up.", objectives = "Use Decimus's pet to scout the Voidspire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90573] = { id = 90573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortify the Runestones: Magisters", description = "We placed a number of runestones throughout Eversong Woods, each one charged with protective arcane magic intended to ward off the Lightbloom.\n\nWhile highly effective, the runestones require an immense amount of power to function. They must be regularly fed with latent arcana lest they weaken.\n\nAs Magisters, it is our duty to maintain the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.", progress = "We must ensure the runestones are charged and defended.", completion = "Your strength is matched only by your acuity, my dear. I will ensure everyone knows how marvelously you have performed today.", objectives = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Misplaced Tomes, then use it to charge and defend a Runestone in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90574] = { id = 90574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortify the Runestones: Blood Knights", description = "The Magisters placed a number of runestones throughout Eversong Woods, each one charged with protective arcane magic intended to ward off the Lightbloom.\n\nNaturally, the runestones require an immense amount of power to function. They can be fed with latent arcana, but that power draws enemies seeking to claim it.\n\nAs Blood Knights, it is our duty to defend the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.", progress = "Maintaining the safety of Eversong is of utmost importance.", completion = "Your deeds honor us, {name}. You have fought well this day.", objectives = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Coalesced Light, then use it to charge and defend a Runestone in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90575] = { id = 90575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortify the Runestones: Farstriders", description = "The Magisters placed a handful of runestones across Eversong, each one charged with arcane magic that wards off the Lightbloom.\n\nAs you might guess, the runestones require a huge amount of power to function. The Magisters feed them with latent arcana, but that kind of power draws a lot of attention. Bad attention.\n\nAs Farstriders, it's our duty to defend Eversong from those kinds of threats--especially when the Haven is looking at us. Go recharge the runestones and fight off whatever tries to stop you.", progress = "We need to keep those runestones safe.", completion = "Nice work. You know how to see a mission through smoothly. I have a few ranger recruits who could learn a thing or two from you.", objectives = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Ranger's Caches, then use it to charge and defend a Runestone in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90576] = { id = 90576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortify the Runestones: Shades of the Row", description = "Have you seen the runestones out in Eversong? Huge rocks full of arcane magic that ward off the Lightbloom.\n\nI'm not the magic type, but I know an opportunity when I see one. Those runestones need a lot of power to work. If we help keep them charged, there are a lot of people who would owe us favors--and favors are even better than gold.\n\nHere's the plan: I help you get some latent arcana, you drop it into the runestones, beat up whatever tries to stop you, then we bask in the accolades. Deal?", progress = "Those runestones aren't going to charge themselves.", completion = "Ha! I shouldn't be surprised you pulled that off so well, but here we are. We've already got people looking at us like we're miracle workers.\n\nAll thanks to you, {name}.", objectives = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Dead Drops, then use it to charge and defend a Runestone in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90601] = { id = 90601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Glowshrooms", description = "Ru'gar used to tell me about how he'd sneak into the nearby cave to harvest glowshrooms. They seemed to be integral to the development of the tla'tak seeds he was cultivating. Will you collect some of the mushrooms within?\n\nOh, and Ru'gar mentioned that the mushrooms have strange properties when harvested. I'm not sure what he meant by that, but maybe stay on your toes.", progress = "Ru'gar mentioned that the glowshrooms helped create a more robust harvest when they were mixed into the dirt he'd planted crops in. How he even figured that out, I'll never know.\n\nI would like to carry on Ru'gar's work. Since we're already here, we might as well gather what we can.", completion = "Ah, you return! And with so many glowshrooms. Excellent. I hope you didn't have anything strange happen.\n\nThank you for collecting all of these. It will take me some time to reproduce Ru'gar's methods, but I have hope now that we can continue his work.", objectives = "Collect 6 Glowshrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90602] = { id = 90602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gomphusta", description = "I would ask one last thing of you. I've heard quite a few of the fungarians mention their leader, Gomphusta. It seems he's behind the uptick in their violence and the reason they're stealing the seeds.\n\nWhile you're in the cave, find him and take him out. Without Gomphusta pulling the strings, the other fungarians will be thrown into chaos and won't be able to organize ambushes as well.", progress = "The fungarians aren't always this violent and aggressive. Gomphusta must be the force driving them. He seems to be the one infecting living creatures with spores.\n\nWith him gone, the fungarians may return to a more balanced state.", completion = "What is this? Ru'gar's notes on his cultivation efforts!\n\nThis is fantastic. I can try to reproduce his work now.\n\nGood work taking out Gomphusta, also. May this throw the fungarians into disarray and keep travelers on the roads safer.", objectives = "Kill Gomphusta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90615] = { id = 90615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Grudge You", description = "You look... different! Ever be to Grudge Pit?\n\nGrudge Pit is great place! Full of fighting and cheering and fungarians. Also decaying!\n\nBoletus is always look for strong creatures to be kill in Grudge Pit. Or for making others be kill.\n\nAre strong creature? Should go to Pit!", completion = "You look like could put up strong fight before start decay.\n\nWould be very interesting!", objectives = "Speak with Boletus at the Grudge Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90616] = { id = 90616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Strong?", description = "You look strong.\n\nShould test yourself in our arena.\n\nSee how you compare to strong fungarians.", progress = "Many fungarians watch the fighting.\n\nAlways so exciting!", completion = "We, uh... you are so strong.\n\nHow, er...? You very different.\n\nTeach fungarians, to be different like you?", objectives = "Kill enemies in the Grudge Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90617] = { id = 90617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Fun Guys", completion = "You found ones to teach?\n\nFirst step is to fight, see what can do!", objectives = "Recruit 3 Fungarians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90619] = { id = 90619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Doesn't Kill Them", description = "Have team, now are ready to fight.\n\nTake your team to empty area. Practice fight, and see what can do.", progress = "We fighting you?\n\nYou are strong.\n\nFight together is good practice for be strong.", completion = "Eyes are open, {name}! We can be strong, too.\n\nWe will be strong, like you!\n\nWhen hurt, fungarians grow stronger. You hurt lot, we grow stronger lot.\n\nMust go tell Boletus we ready!", objectives = "Spar with your teammates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90620] = { id = 90620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Ring", description = "TeamName? Not bad. I like!\n\nYou and the TeamName head on down, and we say words.\n\nYou fight Spore Storm. If beat, fight Cap Clash.\n\nIf beat, fight Fungus Force.\n\nAlways-winners are Glow Guard. You won't beat.\n\nNo run out! Run out is big, big lose.", completion = "Was sure Brakko was strong enough. Was train with strong {name}!\n\nBut Brakko is scared of sporegliders. Will eat cap!\n\nBrakko so sad to fail {name}.\n\nZiny and Tuktuk too. All run out.\n\nWe run out, and Fungal Fellosh were lose.\n\nBut how can not run out, when sporegliders attack?", objectives = "Go fight with your team.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90621] = { id = 90621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiny Heroes' Journeys", description = "You taught them. Why did they run out?\n\nAll fungarians were excited to see if a {race} could teach fungarians for be strong.\n\nYou try one more time, okay?\n\nFirst do what need to get them ready.", completion = "Done teaching, now? Let's see what Fungal Fellowship can do.", objectives = "Help each member of the team overcome their challenges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90622] = { id = 90622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not-Yet Defeated Champions", progress = "The Grudge Pit is always looking for new champions, {name}. Until now, we've just been finding the old ones again.", completion = "Wow, shocked! Fungal Fellowship beat Glow Guard!\n\nI knew {name} strong. But did not know if training could be enough.\n\nNot one fungarian was bet on Fungal Fellowship. We did not think Glow Guard could be defeat. \n\nNow every fungarian know {name} is best teacher of strong!", objectives = "Enter the Grudge Pit and defeat the Glow Guard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90630] = { id = 90630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Bundle of Crystals", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
