quests[90638] = { id = 90638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bundle of Crystals", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90659] = { id = 90659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Borrowed", description = "Now that you have your infinite bronze, we just need to select the right artifact for you, shape the bronze into a suitable simulacrum of the weapon, and then reach through a temporal knot and swap them.\n\nNo one will be the wiser.\n\nAll we have to do is remember to reclaim the simulacrum in this timeline and everything will work itself out.\n\nLet's start by selecting your specialization, that'll determine which artifact we'll be borrowing.", progress = "Every artifacts needs a mighty hero to wield it.", completion = "Intriguing. This artifact's potential has been deepened, perhaps by the fraying of this timeline. It can harness more power than any incarnation of it that I have yet encountered.\n\nLet me record that data point for Moratari.\n\nOh, important reminder--don't forget to recover the bronze simulacrum later or things might get... funky.\n\nAnd lastly, maybe don't mention to people how you got that. It could ruin the experiment.", objectives = "Select your artifact weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90660] = { id = 90660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Golden Circumstance", objectives = "I wish you the best of luck in all your adventures, {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90661] = { id = 90661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dastardly Duos" }
quests[90663] = { id = 90663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing What is Ours", description = "Ve'nari has called in a lot of favors to get the Oasis reclamation effort off the ground. Plenty of Tazavesh merchants have donated to the cause, though some have seen fit to help themselves instead.\n\nA large shipment of stasis-sealed items was stolen from the docks by an untrustworthy importer. I could use someone of your skill to recover the shipment.", progress = "Have you recovered my missing items?", completion = "I wasn't expecting quite so much! Perhaps this is not all my imports? \n\nStill, it's good to see these items. I have a little something for your troubles.", objectives = "Speak with Xy'dax and recover the Missing Imports.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90665] = { id = 90665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved Crests", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90666] = { id = 90666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bundle of Crystals", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90667] = { id = 90667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Runed Ethereal Crest", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90669] = { id = 90669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gold is Gold", description = "Hey! You there.\n\n<Sarvi beckons you closer and lowers her voice.>\n\nYou looking for work? A Magister gave me five gold to find an adventuring type to do some sort of job for him. He said if the person gets it done, I get five more. That'll feed me for months.\n\nYou fit the bill. If you want to try to get paid too, he has a study over by the harbor. Real fancy place--you can't miss it. The guy's name is Aradis.", completion = "Ah, so the ruffian was successful.\n\nYou do certainly look capable. Let us speak, shall we?", objectives = "Speak to Magister Aradis in his study near the Silvermoon Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90701] = { id = 90701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cowardly Cheery Bombs", description = "Goblins love bombs, I get that. But does EVERYTHING have to blow up?\n\nDo me a favor: In the next Dastardly Duos match you enter, find a cheery bomb inside one of the wooden tree and planter props.\n\nAfter you find the bomb, but before it  \"blows up\"... smack it for me. Don't worry, they're cowards.", progress = "Those cheery bombs are asking for it, {name}. Find one in a Dastardly Duos match and smack it!", completion = "Way to go, {name}. You have to show those bombs who's boss, you know?", objectives = "Find a Cheery Bomb, hidden inside a Dastardly prop. Smack it before it blows up.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90705] = { id = 90705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking", description = "Are you curious about your world's history? Would you like to learn more?\n\nLorewalker Cho has been traveling and gathering stories of important events and figures across Azeroth and beyond. If you pay him a visit in your capital city, he will gladly share a tale of the past with you!\n\nOr perhaps more than one tale. He does very much enjoy conversation!\n\nTell him Assistant Lali sent you.", completion = "Oh? Lali is sending vistors my way, now? \n\n<Lorewalker Cho laughs a deep, belly laugh.> \n\nOf course she is! \n\nAh, but she is correct. The only thing I love more than gathering stories is telling them! Sit down, let me share a tale with you.", objectives = "Find Lorewalker Cho in Dornogal, Stormwind, or Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90719] = { id = 90719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowing Corruption", description = "Adventurer, I have made an amazing discovery. \n\nAnalyzing the memories from the time I have discovered that I might be able to recreate the corruption effects that have been wielded in the past. Albeit in a much more controlled way. \n\nI will need you gather some black blood residue from defeating the bosses of the Corrupted or Lost areas of the map and a few more of the displaced corrupted mementos.", progress = "Were you successful?", completion = "Yes, by combining this residue with the displaced corrupted mementos I can... yeah just like so... and then with a bit of my bronze magic... there. Done.\n\nNow that I have a working knowledge I can also make more if you bring me additional displaced corrupted mementos. I will see if I can refine the process anymore. Check back with me later.", objectives = "Find Black Blood Residue and Displaced Corrupted Mementos from the bosses of the Corrupted and Lost areas of the Horrific Visions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90724] = { id = 90724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Sky", description = "All those people. Our army. Our heroes. Our leaders.\n\nGone.\n\nWe are exposed here. Umbric's tether saved us, but we need to ensure we survive this. Report to Lor'themar and tell him what transpired in the Voidspire. I will get Umbric to safety and learn what I can here.", sourceObjective = "Report to Lor'themar in Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[90729] = { id = 90729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Win-Win Situation", description = "Not everything you recovered yesterday was mine, but let's be honest--we're going to keep it anyway!\n\nXy'daz has been ripping people off for years. It's his turn to take a loss!\n\nNow, this can work in both our favors. You sell off half of the leftover goods for me, and I'll let you keep the rest!", progress = "Did you sell the items?", completion = "You did so well! I may have to employ you more often!", objectives = "Sell 6 Shadowtrade Overstock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90731] = { id = 90731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhancing Corruption", description = "Welcome back adventurer. I have made a new discovery but I need to test it out. \n\nHidden in the Lost areas of the Horrific Visions I believe is a rare black blood coagulate. This might be the key to increasing the power of the corruption effects... in a safe way. \n\nIf you can go into these areas and find this item and also bring me back more displaced corrupted mementos I should be able to increase the potency of the corruption effects.", progress = "Were you successful?", completion = "Ok, this is promising... the coagulate catalyzes slower so the increased corruption is more contained... yes, this allows a higher yield of corrupted material without any negative side effects.\n\nAlas, I cannot keep it stable for long. These effects will not last. I am sorry adventurer but we should take advantage of the effects while we can. \n\nAgain, if you bring me additional displaced corrupted mementos I can make you more of these greater corruptions.", objectives = "Find Black Blood Coagulate and Displaced Corrupted Mementos from the bosses of the Lost areas of the Horrific Visions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90733] = { id = 90733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Listener", description = "Now that you've learned about our legends, you've earned the notice of one of our elders. He wants to meet you.\n\nHis name is Aksem, and he knows things that the rest of us have never learned. History that remains hidden, even in the paintings.\n\nGo and introduce yourself. He's expecting you.", completion = "Yes, I wanted to speak with you. \n\nThere are many truths that are hidden, even to the oldest living haranir. Continue to learn and they may be revealed.\n\nShow respect to our history, and I will eventually tell you more.", objectives = "Speak to Aksem in the Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90734] = { id = 90734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Name of the Goddess", description = "The high priest Aksem has asked for you again. He said you are not the only one on a quest for knowledge about the deep history of Harandar.\n\nGo to him. I believe he already has another guest who is also interested in learning this hidden history.", objectives = "Return to Aksem in the Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90735] = { id = 90735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Staff", description = "This time, I do not have a story for you. \n\nInstead, Aksem has asked that you meet with him to help recover the next of the relics. Go to speak with him, and he will tell you more of what you must do.", sourceObjective = "Speak to Aksem in the Den.", sourceObjectiveStatus = "unverified-source-field" }
quests[90736] = { id = 90736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Not Yours", description = "The rutaani in the Blossoming Terrace are crafty. They've trained their petalwings to search and grab anything shiny that rolls down from the Den.\n\nAnd, I suspect, sometimes they grab things that haven't naturally fallen.\n\nSo we want to get those things back. That's where you come in.\n\nGo into the terrace, and don't hesitate to use force to send a message. That's a language we all understand.", objectives = "Retrieve 8 Stolen Belongings from the Blossoming Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90737] = { id = 90737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nested Clues", description = "You're looking for a staff called the Root of the World. It's a powerful twist of woven roots, back from before the haranir traveled deep into the mountain.\n\nIt's irreplaceable, as Aksem knows. So if a rutaani petalwing stole it, that's embarrassing. The only way for everyone to save face is to get it back.\n\nSearch the nests of the bigger birds. They've been trained to look for more valuable items.", objectives = "Uncover clues about where the stolen rootstaff could be.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90738] = { id = 90738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Blossoming Terrace", description = "When the haranir first arrived in Harandar, they brought with them a staff formed of the roots of a great tree. That tree has since gone away, but the roots remain.\n\nIt has been our duty to protect that staff and pass it on through the generations, but now it has been stolen.\n\nYour task is to find it and return it to Zur'Ashar Kassameh.\n\nGo into the mists below the Den and seek out the Shul'ka. They will guide you on your search.", sourceObjective = "Meet Shul'ka Seila outside the Blossoming Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[90739] = { id = 90739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of Things", description = "Looks like you didn't find any sign of the rootstaff among all the thiever's nests. That's a good thing, honestly.\n\nBut there's more to this test than just recovering stolen goods. Yes, it's a test. You're seeking secret knowledge. That means something here doesn't add up, and the real answer is waiting to be found.\n\nSo, come find me when you're ready to get that answer.", objectives = "Follow Shul'ka Seila and recover the missing staff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90740] = { id = 90740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Legend to Know", description = "I am entrusted with many secrets, and the benefit of that is not having to explain myself often.\n\nYou have recovered the Root of the World, as I asked. Now, take it to Zur'ashar Kassemeh, and learn more about it.\n\nThere will be more for you, later.", sourceObjective = "Return to Zur'ashar Kassameh.", sourceObjectiveStatus = "unverified-source-field" }
quests[90747] = { id = 90747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrong Bluecephalus", description = "We may have gotten off on the wrong foot, but there's something you should know.\n\nThat old slateback you used to haul all those imports? I thought it was just another worn-out nag, but it turns out it was the real treasure all along.\n\nA rare bluecephalus, worth a fortune!\n\nYou might want to figure out where it went, and why Ba'eth isn't exactly rushing to share the profits!", progress = "Are you ready to help?", completion = "Good. This will be a profitable venture... for me.", objectives = "Speak with Ba'eth and others.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90749] = { id = 90749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Mutual Enemy", description = "<Liadrin lowers her voice, speaking only to you.>\n\nWe have two choices. We can either continue to talk to the Amani or fight our way inside.\n\nI would still prefer to negotiate passage with Zul'jarra, but if our diplomacy goes awry, be ready.\n\nFor now, follow my lead.", completion = "I must say I am... surprised that Zul'jarra allowed us passage. It has been many years since I or anyone from Eversong has stepped foot on this side of the border.\n\nStay sharp. This is a volatile situation. We may have to do more to engender their trust.\n\nBut don't turn your back on the Amani.", objectives = "Follow Lady Liadrin into Zul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90751] = { id = 90751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber Processing" }
quests[90754] = { id = 90754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skyriding", description = "This land is more vast than I remember. However, a good scholar is always prepared.\n\nTo cover more ground, you will need a winged mount and the skill to ride it swiftly.\n\nI recall Lord Andestrasz helping us with this in the past, near the Timeless Isle in Pandaria. Let's send you back to that moment in time, so you can learn from him.\n\nDon't wander too far in distant lands, you're still needed back here. Return via the portal when you have finished your instructions.", progress = "All things come with practice.", completion = "Let us get started. We will focus on the basics.\n\nDo not worry, the fancy maneuvers will come later.", objectives = "Take Moratari's portal to Lord Andestrasz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90755] = { id = 90755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Flies", description = "That should suffice for now. Remember the basics and you will improve in time.\n\nSpeaking of time, you had best be on your way. The portal there will take you back to Moratari.", completion = "Excellent. This should expedite our research.", objectives = "Return to Moratari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90759] = { id = 90759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cult Within", completion = "Thank you for coming, {name}. The Twilight's Blade cannot be allowed to roam our cities.", objectives = "Meet Magister Umbric in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90760] = { id = 90760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avoiding Blame", description = "Apocalyptic threats have taken many forms in Azeroth's history, but today we face Xal'atath and her Twilight's Blade.\n\nI fear that people are falling into hopelessness as the Radiant Song cries a warning. The Twilight's Blade could use that despair to draw them into their ranks.\n\nMy mages have identified this district as housing a peculiar amount of void energy. Investigate and stop any cultists you may find.", progress = "I understand the comfort the void can provide. But surrendering to it completely is not the peace many are led to believe.", completion = "There are Twilight's Blade in the city. If they are here, they are certainly recruiting elsewhere.\n\nWe have more work to do.", objectives = "Disperse 6 Suspicious Citizens in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90761] = { id = 90761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avoiding Blame", description = "The cult of twilight has long been dedicated to ending Azeroth. That they ally with Xal'atath is no surprise.\n\nIf the Twilight's Blade are indoctrinating citizens, we must stop them. We cannot permit the weak to fall to the Void's dark designs.\n\nThe Cleft of Shadow is home to many practitioners of unsavory magic. Identify and end any cultists you may find there.", progress = "<Rommath sneers at you.>\n\nThe calm and comfort the Void offers is a lie. You would do well to abandon it.", completion = "The Radiant Song casts a long, dark shadow on Azeroth. The Twilight's Blade are taking advantage of it.\n\nWe have work to do.", objectives = "Disperse 6 Suspicious Citizens in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90762] = { id = 90762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Highlands", description = "I've spoken with Grand Magister Rommath. Despite our differences, it seems we are aligned in purpose.\n\nWe have both found evidence that Twilight's Blade cultists are convening in the Twilight Highlands. It's a place long scarred by the cult's misdeeds. And it's a suitable staging ground for an attack.\n\nMeet us there so we may continue our investigation.", completion = "Well. It seems we are to be working together to investigate the Twilight's Blade.\n\nI do hope you're prepared.", objectives = "Meet Grand Magister Rommath in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90763] = { id = 90763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Highlands", description = "I've received word from Magister Umbric. He has found similar evidence that the Twilight's Blade are recruiting in Stormwind.\n\nThe Void poses an existential threat to all of Azeroth. We must stop the cult at its source.\n\nWe've agreed to meet in the cult's homeland, the Twilight Highlands. Find me there so we may continue our investigation.", completion = "Good, you've arrived. \n\nKeep an eye on our allies. We may be working with them to stop the Twilight's Blade, but the Void is insidious. \n\nThey cannot be fully trusted.", objectives = "Meet Grand Magister Rommath in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90764] = { id = 90764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cult Within", completion = "Good, you're here. We cannot let the Twilight's Blade gain ground in the city.", objectives = "Meet Grand Magister Rommath in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90765] = { id = 90765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight Dress", description = "Cult activity in the area has risen significantly. While we are gathering troops, you secure a cultist disguise and infiltrate their nearby training grounds.\n\nFind out anything you can about the Twilight's Blade and their goals. I will keep this area secure.", progress = "You look lost, fledgling. Isn't there somewhere you should be?", completion = "You hardly seem prepared to serve Xal'atath. We shall fix that.", objectives = "Find a Twilight's Blade disguise and infiltrate the Twilight's Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90766] = { id = 90766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xal'atath's Proven Faithful", description = "It takes more than blistering desperation for the apocalypse to be part of the Cult of Twilight.\n\nWe are Xal'atath's Twilight's Blade. Our purpose is greater than it has ever been before. And thus, we must become her strongest allies.\n\nGo and train with my associates in the field. Educate yourself on our rituals and rhetoric. Only then will I allow you to go through the initiation ceremony.", completion = "Excellent. You have the bearing of a true acolyte of the Twilight's Blade.", objectives = "Train to become a Twilight's Blade cultist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90767] = { id = 90767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Doom", description = "Having completed your training, you have earned full membership with the Twilight's Blade.\n\n<Harrowtongue pauses a moment, appearing self-satisfied.>\n\nAs a member of the cult, you will now join your fellow acolytes in an initiation ceremony. They are in the basement of this building receiving instructions from our great leader, Mor'duun.\n\nAllow his words to fill you with zeal for the cause. The end is near!", progress = "Have you discovered more about the cult's plans?", completion = "I suppose aligning with yet another being hellbent on ending the world is only fitting for the Cult of Twilight.", objectives = "Sabotage the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90768] = { id = 90768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cult It Out", description = "Mor'duun and his Twilight's Blade cultists are directly supporting the Harbinger's dark designs for our world.\n\nAnd that is all we need to know. Kill as many as you can, then meet us back at our base of operations.\n\nThe cult and its leaders must be eliminated.", completion = "Their nefarious alliance with Xal'atath is clear. Good work. Now we take them down.", objectives = "Kill Gehl Harrowtongue and 12 Twilight's Blade cultists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90769] = { id = 90769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue for You", completion = "May the spirits protect you mon, and your new blue friend!", objectives = "Receive your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90770] = { id = 90770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grift", description = "Dey say you want the blue beast. Was a great bargain I stumbled upon. Da bazaar full of opportunities. \n\nMany more bargains to find in spots where treasures lie waiting. \n\nYou know where to look?\n\nGo to dis special place and find treasures, I give the blue beast to you.", progress = "Did you find da treasures?", completion = "Good work, mon. Griftah be smiling today.", objectives = "Enter Untethered Space and recover the items Griftah requires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90772] = { id = 90772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flames Rise Higher", description = "De coal... it's white-hot now. And I feel like there is somethin' inside it?\n\nBrek said dis was de last trial. But Jan'alai is not here.\n\nWhat do we do now?\n\n<Zul'jarra looks at Brek and scowls.>\n\nTalk to Brek and see if he's got anything to say we can understand.", progress = "If I cannot commune with Jan'alai, de path of de hash'ey stops at dis temple.", completion = "We did it, hash'ura.\n\nJan'alai is reborn! And we have her blessin'.\n\n<Zul'jarra closes her eyes and briefly enjoys the feeling of the flame against her face.>", objectives = "Complete the ritual of Jan'alai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90773] = { id = 90773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meat My Business", description = "Since I am helping you, I'm sure you won't mind returning the favor.\n\nI have a constant need for fresh, untainted meat, which is quite hard to come by. The Oasis is off limits, but the wildlife roaming these sands?\n\nI've got a list of what I need. Bring me those items, and I'll tell you what you need to know.", progress = "You've collect all the meat?", completion = "Now as I promised.\n\nI sold the blue slateback to an outsider like yourself. Not some great hero, but more of an awkward sort.\n\nCome back tomorrow. He usually stops by here for a meal. And he doesn't merely smell it, he eats!", objectives = "Collect 12 Dustback Flank, 5 Siltwing Tail, and 5 Swoopwing Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90776] = { id = 90776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip a Combat Curio to Brann Bronzebeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90778] = { id = 90778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip a Utility Curio to Brann Bronzebeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90779] = { id = 90779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracked Keystone", description = "Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive.\n\nPerhaps performing a suitably impressive task will stabilize the stone's magic once more?", objectives = "Complete any dungeon on Mythic 2 or higher difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90781] = { id = 90781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: K'aresh", description = "There's rumors about conflict rising in K'aresh - go off and find out more!", progress = "Go off and finish what you started.", completion = "I'm astounded at your quick return, well done.", objectives = "Collect 100 Sparks of War in K'aresh, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90782] = { id = 90782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nethersent", description = "<The draenei first tries to speak to you in his native tongue, adapting after you fail to respond.>\n\nMen of Void take us to here. Come from sky. Fighting, killing. Want to go back. Help brothers and sisters.\n\nShow you.", completion = "<The woman seems wary of you, but nonetheless bows at your approach.>\n\nFriend? Hope of us.", objectives = "Free the draenei and meet with him at the base of Masters' Perch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90818] = { id = 90818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Loose Lips", description = "It is not unexpected to sense some fel magic here. There are still warlocks in the city and old fel siphoning chambers. But the evidence I've found so far is more than could be explained by just that. It feels... different. Chaotic.\n\nThis practice has to be widespread, which means someone must be talking about it.\n\nI've been rooting around too long to go unnoticed, but perhaps you could covertly listen in on some idle banter around the city. If you learn anything useful, report back to me.", progress = "People let many things slip when they assume they're unheard.\n\nNever assume you're unheard.", completion = "<Belath's expression sours more than usual.>\n\nFear drives people to desperate measures, but fel magic isn't a weapon to be wielded lightly.\n\nThe power comes at a cost they do not understand--nor are they trained to withstand those dangers.", objectives = "Listen in on 3 conversations near the Royal Exchange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90819] = { id = 90819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Acting the Part", description = "Based on what we discovered, I believe the fel is coming from Murder Row. Someone there is breaking down Legion relics and infusing the magic into mana wyrms for covert siphoning--and people are buying it up in droves.\n\nWe need to figure out who that someone is.\n\nTake this wyrm core with you into the Row and look for more of them. The promise of coin should get you in front of the right person.", progress = "The denizens of Murder Row are tight-lipped, but any information we manage to uncover will be invaluable.", completion = "They mentioned someone named Zaen?\n\nHe's a well-known thug in the Row. Smuggling fel through the Silvermoon Harbor sounds exactly like his style. He doesn't want anyone watching him.\n\nGood work pocketing that shipping manifest.", objectives = "Take the Cracked Wyrm Core, then investigate Murder Row to discover the source of the smuggled fel wyrms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90821] = { id = 90821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Harbored Secrets", description = "That manifest is stamped by the Silvermoon Harbor. It looks like Zaen has his smugglers working there to push his fel relic shipments through inspections.\n\nIf we cut off their supply line at the harbor, we can halt the fel operation until we track down Zaen and end it for good. No sense going after the middlemen until then.\n\nSubterfuge got us this far, so let's keep at it. Head to the harbor and tell them you're picking up Zaen's shipment. We'll work from there.", progress = "Zaen is the mastermind here, or at least he seems to be. We'll need to deal with him to truly end this scheme.\n\nTaking out their fel supply line at the harbor will stop the situation from getting any worse while we find him.", completion = "The \"Illicit Rain?\" Zaen's base of operations, perhaps.\n\nThat receipt mentions Suramar. The fel relics must be getting pilfered from the Broken Isles, then routed into Silvermoon through a trade line no one would suspect.\n\nClever.", objectives = "Talk to the dockmaster at the Silvermoon Harbor to collect Zaen's fel relic shipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90822] = { id = 90822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: One Fel Swoop", description = "We have all the puzzle pieces. Zaen smuggles fel relics from the Broken Isles by stacking the Silvermoon Harbor with his own smugglers. The relics are processed in Murder Row, then fel magic is infused into mana wyrms for sale and siphoning.\n\nSuch a convoluted operation might be impressive, if the goals weren't so reckless. Zaen is preying on people's fear. He doesn't care who he helps or hurts as long as he rakes in the gold.\n\nLet us end it. We'll find the Illicit Rain in Murder Row and clear it out.", progress = "Something seems to have happened in Murder Row since we left. A crowd is forming.\n\nProceed with caution. I'm with you.", completion = "With no one left to run it, this fel operation should be done with... for now, at least.\n\nIt was a pleasure working with you, {name}.", objectives = "Dismantle the fel smuggling operation inside Murder Row.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90824] = { id = 90824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Brother's Alive!", description = "En'liahn saved me from the Rift of Aln. He's my older brother. I know it was stupid to go there, but it wasn't my fault!\n\nWe all thought En'liahn was dead, but I saw him earlier at the wetland. When he saw me, he ran away.\n\n<Chua looks sad.>\n\nNo one here believes me and now I can't go. Will you help me find him again?", completion = "Chua sent you? He's not out here again is he?\n\nMind lending me a hand?", objectives = "Find En'liahn at the Ahl'ua Wetland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90826] = { id = 90826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Healing Waters of Ahl'ua", description = "I'd hoped Chua hadn't seen me. Better he thinks I died. Instead, I'm self-exiling.\n\nI was trapped in the Rift of Aln while saving him. Being in there for so long corrupted my connection to the goddess--if I don't sever it soon, it'll drive me mad, or worse.\n\nThe Shul'ka who saved me has agreed to mentor me through the process. He told me to come here and gather some things for a ritual to sever the connection.\n\nI must collect the nearby healing waters. Will you help me fill this jug?", progress = "I appreciate your help, {name}.", completion = "Thank you, {name}.\n\n\n\nI hope the water is as powerful as my mentor says it is. The strong poison of these creatures suggests I'm going to need it to survive the ritual.", objectives = "Collect 6 Healing Waters of Ahl'ua.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90827] = { id = 90827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only the Poisonous Parts", description = "My Shul'ka mentor instructed me to collect the toxic glands from the creatures here. He said they were crucial to the Ritual of Severing in order to break my connection with the goddess.\n\n<En'liahn shakes his head in pain.>\n\nI'm not looking forward to whatever this ritual is, but her disjointed song in my head is getting stronger and making it hard to focus.", progress = "Be careful handling that poison. These creatures are some of the deadliest in all of Harandar.", completion = "This should be more than enough.\n\nI'll be careful with them. I wouldn't want to poison myself prematurely.", objectives = "Collect 8 Phytogenic Poison Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90829] = { id = 90829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting My Mentor", description = "I'm in your debt, {name}. I didn't think I'd get any help. My mentor only provides guidance. He says that is the way of the Shul'ka.\n\nThanks to you, I have everything I need for the ritual. Will you continue on with me? I'm heading for the cliffside overlooking the Rift of Aln to the northeast.", completion = "I'm glad you came. Amarakk is my Shul'ka mentor. He says your help is not strictly forbidden.\n\nI can use all I can get.", objectives = "Rejoin En'liahn on the cliffside above the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90830] = { id = 90830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path Will Reveal Itself", description = "The next step is to locate the ritual site. It's different for each potential Shul'ka.\n\nAmarakk says that I must open myself to the power of the rift--that some part of myself tied to this place will guide the way.\n\nAll I can tell you is it hurts.\n\nAre you still with me?", progress = "I see you made it.", completion = "Now it is time to see if young En'liahn will survive the ritual or be consumed by the rift.", objectives = "Travel with En'liahn to discover the ritual site within the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90831] = { id = 90831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing Is Becoming", description = "If En'liahn is to succeed as a Shul'ka, he must learn to disrupt the manifestations in the rift. Sometimes that means closing small tears as they open. Most of the time, we simply slay the manifestations where we find them so they do not become so numerous as to threaten the rest of Harandar.\n\nIt is a never-ending responsibility each of us bears. It is why we are Shul'ka.\n\nThis, of course, assumes that he survives the ritual, or even survives to find the ritual site.", progress = "I see you, {name}.", completion = "You have done well for one who is not Shul'ka.\n\nUnfortunately, the Rift of Aln never rests. I think you'll be back.", objectives = "Disrupt the manifestations within the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90832] = { id = 90832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As Her Voice Goes Silent", description = "En'liahn is about to drink the mixture of the poison and healing waters to begin the ritual. He will be unconscious and fighting for his life.\n\nThe manifestations of the rift can sense this, and they are gathering.\n\n{name}, you must place the wards and use their power to defend him while he severs his final connection to the goddess before her song drives him to madness.", progress = "Whatever happens next, you've proven you can be trusted.", completion = "It is done. There is but one thing left to do once En'liahn has recovered.\n\nBut first, we should leave the rift immediately. This is no place to linger.", objectives = "Protect En'liahn while he endures the Ritual of Severing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90833] = { id = 90833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Rite", description = "Foolish. En'liahn is still weak from the ritual and not prepared.\n\nHe has run off to confront Morta'ka the Sundered Echo. This is the final rite of all who would become Shul'ka, but it is usually only attempted after years of preparation.\n\nEn'liahn will not survive, and in dying will only make Morta'ka more powerful. Will you save him, {name}?", completion = "I know it was stupid and I should be dead. I feel confused about surviving the ritual but no longer being able to hear the goddess. I'm sorry, {name}. I shouldn't have done that.\n\nAt least it's over. Now to apologize to Amarakk. He's probably done with me.", objectives = "Help En'liahn to slay the manifestation known as Morta'ka the Sundered Echo inside the Shadow Cleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90834] = { id = 90834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From This Point Forward", description = "I don't know how to feel about losing my connection with Aln'hara. There's no more pain... I'm not going mad, but there's a hole inside. Does that make sense?\n\nWill you rejoin us back up on the cliff?", completion = "I owe you a great debt, {name}. At least now I can protect my people as I learn the ways of the Shul'ka.\n\nMy only regret is being separated from Chua.", objectives = "Return to En'liahn and Amarakk on the cliff overlooking the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90835] = { id = 90835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Rumors Abound", description = "I would advise exploring the city with caution. Not all is what it seems in Silvermoon.\n\nThe Illidari are performing an investigation which need not be spoken of openly. But you appear formidable... Perhaps you can aid us.\n\nMy commander, Belath Dawnblade, is heading the investigation. The last I heard, he was surveying the upper terraces of the Bazaar.\n\nSeek him out, if you would make use of yourself.", completion = "Your arrival is timely.\n\nI will be brief: I believe there is a widespread resurgence of fel magic use happening in Silvermoon, and it must be stopped.", objectives = "Find Belath Dawnblade in the terraces above the Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90837] = { id = 90837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row: Traces of Fel", description = "I have been sensing powerful fel magic throughout Silvermoon, but this is the first origin point I could locate. The rest were too faint, or perhaps deliberately hidden. Fortunately, this means we now have a specific area to comb through more closely.\n\nWe need to gather more evidence. Go around this area and see if you can find more hidden sources of fel. I will grant you a temporary portion of my sight so that even the slightest hint of fel magic will be obvious to you.", progress = "Were you able to locate anything?", completion = "Hm... Legion scraps, fel dust, and evidence that both might be getting moved around the city covertly. A sanctioned fel trade would not be resorting to such measures.\n\nThen there are the mana wyrm cores we both found. Siphoned dry, but fel still clings to them.", objectives = "Discover 5 sources of fel magic near the Royal Exchange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90838] = { id = 90838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oaths and Heirlooms", description = "You, stranger... do you know of the Shadowguard that left K'aresh in ruins?\n\nMy sister was lost in the conflict, her heart forcibly turned to the Void, but I swore oaths to my family... to cherish them no matter their transgressions.\n\nMy sister, Veraan, is surely lost, but if I were to recover her necklace, at least then my oaths would be upheld in spirit.\n\nI am a simple tinkerer. I've tuned this device to track the Shadowguard, but I cannot face them alone.\n\nWould you help me?", completion = "Keep yourself out of sight. I would rather not risk a bleak fate.", objectives = "Meet Kifaan outside of the Ethereum Overcroft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90840] = { id = 90840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Your Specialty?", description = "The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared.\n\nYou're strong enough now that you should choose a combat specialization.\n\nThis will unlock a new array of abilities for you to face the dangers within the Dragon Isles.\n\nGo ahead and choose your combat specialization.", progress = "Having trouble? You can find your combat specialization beside your spellbook.", completion = "Excellent choice! I'm looking forward to what you do next.\n\nTake this riding mount. It'll help you get around here faster.", objectives = "Choose your combat specialization.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90842] = { id = 90842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Is Where the Hearth Is", description = "Before you head off, you'll want to get yourself a Hearthstone. \n\nThis little stone will return you to the inn where you last bound it to.\n\nIt's not much of an \"inn\", but the explorers have a tent set up. \n\nTest out that new mount of yours and ride over to Sil'nori Crestshade. He'll get you sorted out with a Hearthstone.", progress = "Sil'nori Crestshade nearby can get you set up with a Hearthstone.", completion = "If you ever find yourself lost, use your Hearthstone to get yourself back to where you should be.", objectives = "Ride your mount, then speak with Sil'nori Crestshade to get a Hearthstone bound to the Wild Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90843] = { id = 90843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Dragon Isles", description = "It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span.\n\nNaleidea Rivergleam of the Dragonscale Expedition could use your help.\n\nSafe travels, {name}. I look forward to our next meeting!", completion = "How are you? We could use more hands to help us explore the Dragon Isles!", objectives = "Meet  Naleidea Rivergleam to begin your adventure in the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90844] = { id = 90844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fits of Lucidity", description = "While I've been lurking, I've been listening.\n\nThese Shadowguard appear to have a minor rebellion on their hands. Some of the ethereals are acting erratically. They're being rounded up and questioned.\n\nWhat's going on here?\n\nDispatch some of these Shadowguard and intercept their intel. I'll decode anything you bring back to me.", progress = "I thought the Void coursing through these ethereals was all-consuming.\n\nAnd yet, there seem to be some able to resist its infinite darkness.", completion = "Something has sparked a rebellious fire in some of the Shadowguard.\n\nLet us see what more we can find.", objectives = "Slay ethereals in the Ethereum Overcroft and collect 8 Interrogated Data.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90845] = { id = 90845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distant Memories", description = "I swore an oath to honor my family... difficult when my sister was converted to the Shadowguard. She may not be here, but tracking the Shadowguard has led me to this place. \n\nI'm looking for a necklace that belonged to my sister Veraan. It's odd... I've noticed many K'areshi heirlooms discarded around here. It seems the Shadowguard wish to destroy any reminders of our home world.\n\nIf you bring some of these trinkets and baubles to me, we can see if there are any I recognize.", progress = "These keepsakes are some of the last remnants of our home world.\n\nThe memories they contain are powerful. The Shadowguard is right to fear them.", completion = "I do recognize some of these items! They belonged to close friends and family.\n\nIf my sister's necklace is to be found, it will be here.", objectives = "Collect 8 K'areshi Keepsakes found at the Ethereum Overcroft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90847] = { id = 90847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truth From Power", description = "Thanks to your intel, we have learned that the rebels are being interrogated by Questioner Xen'daan.\n\nIt is said that after being questioned, the rebel ethereals are being taken somewhere to be \"dealt with.\"\n\nThe head questioner is sure to know more. If we can find where they've taken the rebels, there may still be hope for them.", progress = "At the risk of getting my hopes up... do you think Veraan could be among them?\n\nCould I face her now? After the atrocities she's committed in the name of the Void?", completion = "{name}! This necklace belongs to Veraan! Veraan IS Sombersong!", objectives = "Slay Questioner Xen'daan at the Ethereum Overcroft to discover the rebels' whereabouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90848] = { id = 90848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Started the Fire", description = "Veraan is sure to be amongst the rebels taken to Shadowguard Point.\n\nHer fiery spirit fills me with great pride!\n\nI came here expecting to say a farewell of sorts. I did not come here expecting to find my sister.\n\nPerhaps it's not too late, {name}!", completion = "Veraan's essence may have been twisted by the Shadowguard, but the rebellion gives me hope.\n\nCan the dissidents be snatched from the Void's grip entirely?", objectives = "Meet Kifaan at Shadowguard Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90849] = { id = 90849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Show" }
quests[90851] = { id = 90851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eating Their Own", description = "The Shadowguard seem to have no qualms caging and torturing their own kind.\n\nThe last thing I want is more violence amongst the people of K'aresh, but better them than us.\n\nDisrupt their operation by subduing some of the Shadowguard.", completion = "Violence is rarely an occasion for celebration, but I am glad we have at least slowed the deeds occurring here.", objectives = "Slay 12 Shadowguard Engineers and Infusers at Shadowguard Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90852] = { id = 90852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Techno-Magnetic Pulse", description = "The betrayers are being held in stasis chambers.\n\nI've seen these cages before. Their design is efficient but fragile. They will fail with the slightest energy variation.\n\nFind crackling energy vessels strewn about and heave them at the stasis chambers. With true aim, you will disable them and free the betrayers.", completion = "Thank you, {name}. You helped me see my sister again. For that, I can never repay you.\n\nVeraan is changed. Angry. Tormented by despair. Let us tread delicately.", objectives = "Throw Crackling Energy Vessels at arcane prisons to free the Caged Betrayers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90858] = { id = 90858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repress the Oppressors", description = "We were brought here to face the wrath of Soulbinder D'zaar. She commands the Shadowguard here. She leverages the power of the Voidstorm to convert souls to energy that she consumes.\n\nShe and her loyalists are traitors to our kind!\n\n<Veraan grimaces in pain as the Void courses through her.>\n\nThey must be stopped... their devices dismantled... their will ended...\n\n{name}... destroy them all!", progress = "<Veraan trembles with rage.>\n\nThese kinslayers were willing to sacrifice their own. And in service of what? Xal'atath's will?", completion = "I can feel Kifaan's hesitation every time our gaze meets. He is afraid of me...", objectives = "Disrupt the operation by slaying ethereals, destroying Fragile Energy Piping, and detonating Volatile Energy Reservoirs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90860] = { id = 90860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shedding the Yoke", description = "Rebels like us are brought to Soulbinder D'zaar. She suffers no betrayers.\n\nOur fate was to be sacrificed--our souls converted to energy. D'zaar works the conduit with arcane mastery to absorb these souls!\n\nWe don't have much time. I can feel the Void pressing from within. If we are to leave this life violently, D'zaar and her conduit are coming with us!", progress = "The pressure is building... it's almost time...\n\nAnd besides, do I even deserve to live? What will they say of me, a member of the Shadowguard, when all is said and done?\n\nDo you think Kifaan could ever forgive me?", completion = "The Shadowguard got what they deserved.\n\nBut I am not blameless, {name}. Even now, shadows linger inside me.\n\nFor the safety of everyone, I should go.", objectives = "Slay Soulbinder D'zaar at Shadowguard Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90866] = { id = 90866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Universal Language", description = "To go home, water of life. Need.\n\n<Tul'amar attempts to discern if you understand what she's talking about with a look. After a pause, she opts to stab her own fingertip with the end of her staff and then displays a bead of her blood to you.>\n\nThis. Of here. Is of fight. Of fight is Void. Void is power. With power, go home.\n\n<She shows her fangs with an exaggerated snarl before pantomiming a claw swipe.>\n\nWater of life. Of beast. Much. Yes?", progress = "You. Not die? Good.", completion = "Blood! Is blood. Yes?\n\n<She looks to one of her kin, who assures her that she's got the right word this time.>\n\nGood. Now see.", objectives = "Collect blood from the beasts north of the Night Trench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90869] = { id = 90869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All in the Image", description = "So, the higher-ups in the marketing department say you need a good partner to soften your aesthetic of... you know, \"murder everyone around me for gold.\"\n\nWe've got two focus group approved goblins over there ready to go, so go take your pick. Sassy will handle the paperwork.\n\nOh, don't give me that look. You only gotta forever-love each other in front of the public. Once the cameras are off, no one cares. It'll be great for your reputation!", progress = "C'mon, this ain't rocket surgery. Pick whoever you wanna pose on some magazine covers with.", completion = "There we go! Nice and artificial, just like all the best marketing should be.\n\nAnd I just finished the paperwork for your other big image upgrade. I think you're really going like this!", objectives = "Speak to Sassy Hardwrench to select a \"marketing partner.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90870] = { id = 90870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Grub", description = "Ah, ye're here! Brewfest is here and we've got a small problem. We can't have a proper feast without the food, but some pesky hozen thought it'd be fun to steal our bags of grub. I'm sure they're just lookin' to fill their own bellies, but it's messin' up our plans!\n\nSo here's what I need ye to do: hunt down those hozen and take back the bags they've snatched. There's a good chance ye'll find a few bags just sittin' on the ground too. When ye return, just add the recovered bags to that wagon back there.", progress = "The feast won't come together without those ingredients!", completion = "Ah, ye've done it! The cooks will be pleased.", objectives = "Collect Bags of Brewfest Ingredients and deposit them at the wagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90872] = { id = 90872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drenched In It", description = "<Tul'amar looks away from the blood-soaked and mortified Juras, and toward the portal as it flickers to life. She reads it with her powers of the arcane.>\n\nGood. Blood is vio... violent? Violent is power. Need more. Now, brothers and sisters.\n\n<She gestures to the blood in your possession, and then to her people. Many of them return wary looks your way.>\n\nYou can. I say. \n\nThen, go out. See of me.", progress = "Done?", completion = "Good. Now, more. Brothers and sisters, help.\n\nAnd men of Void, kill.", objectives = "Mark 8 Offworld Refugees with Predator Blood to empower the portal in Exiles' Hovel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90873] = { id = 90873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "These Violent Delights", description = "Brothers and sisters. Here. Help.\n\n<Tul'amar connects her thumb and index finger on both hands to make a chain. Then, she breaks the link with a sharp gesture.>\n\nHow? Show.\n\n<She then produces a glimmering relic and holds it over her gauntlet. She spends a portion of her arcane energy into it. Its newly activated magic forces the straps holding her glove in place loose.>\n\nUse.", completion = "<Tul'amar tilts her head at the freed draenei hiding behind her.>\n\nI see. Good. You good.", objectives = "Use the Relic of Liberation to free 10 Master's Prospects and 3 Unwilling Summons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90874] = { id = 90874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Violent Ends", description = "Go home. How?\n\n<She offers a dramatic flourish with her fingertips, producing some arcane sparks. Then, she makes an X with her index fingers.>\n\nOf me? No. Of they.\n\n<Tul'amar gestures to a group of voidwalkers up ahead. She then draws her thumb across her neck.>\n\nKill. And.\n\n<She reaches into a pouch on her hip and retrieves a cracked stone of domanaar make. It looks like a spell reagent of some kind.>\n\nAs this. Need.", progress = "<Tul'amar holds still, even as you approach.>", completion = "<She counts out the portal runes in your possession and nods in approval.>\n\nYes. Good.", objectives = "Collect 8 Abductor's Marks from the voidwalkers of Masters' Perch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90875] = { id = 90875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across Worlds", description = "Man of Void. Have key. Need. Key to home.\n\n<Tul'amar gestures down the way to the northwest. She grimaces back at her injured kin.>\n\nGo back, we. Wait. Hope. For you.", progress = "<Tul'amar smiles sadly at her people.>", completion = "Stay. I must. Men of Void, cannot find brothers and sisters. Finish, must. Only I.\n\nYou, good. Friend. But. Trust, can't. Trust, only when brothers and sisters safe.\n\n<She then holds her staff forward, offering it to Juras. Though he seems reluctant to take it, Tul'amar does not waver.>", objectives = "Kill Snaerius and recover his Lodestar of the Great Dark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90879] = { id = 90879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewmaster's Kitchen", description = "Now that ye've gathered the materials, we can get to cookin'! We'll need plenty o' food for the whole crowd.\n\nWe've got a short but sweet menu: Barley Soup, Pretzels, and of course a good ol' brew!\n\nAre ye ready to learn the ropes?", progress = "Get cookin'!", completion = "Ah, I can smell the pretzels from here. Ye've cooked up a spread that'll keep even the pickiest dwarves satisfied!", objectives = "Follow the steps to cook Brewfest food and a delicious Brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90880] = { id = 90880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serving with Style", description = "Ye've done well in the kitchen, now it's time to learn how to serve! Brewfest isn't just about food--it's about makin' sure everyone has a good time.\n\nYe'll be takin' orders, deliverin' dishes, and pourin' drinks with a smile.\n\nGet out there and show 'em how it's done. Brewfest won't run without good service!", progress = "Remember to serve with a smile!", completion = "I'd say ye've earned yerself a nice break and a brew after all of yer hard work. But don't get too relaxed! There's still plenty to do to keep Brewfest runnin'!", objectives = "Take the customer's order and serve the food to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90882] = { id = 90882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnoll Way", progress = "Handle those gnolls while we figure out our next move.", completion = "Excellent job. However, we cannot rest.\n\nWe have word of more chaos in the highlands.", objectives = "Slay 10 gnolls within Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90883] = { id = 90883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Go'shek Farm", progress = "Find Farmer Bruvk outside of Go'Shek Farm.", completion = "I never thought I'd get this much help! Please, you have to stop them!", objectives = "Travel to Go'shek Farm", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90885] = { id = 90885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Beautiful Pumpkins", description = "The kobolds and ogres appeared out of no where and kicked us out of the farm!\n\nI thought this was some Alliance plot until you all showed up. Maybe the Alliance is here to help us after all.\n\nYou have to help me get my precious pumpkins back. I've spent the entire harvest cultivating them!\n\nYou lead the way. I'll grab the pumpkins when you find them.", progress = "Return to Thrall with Farmer Bruvk and his pumpkins", completion = "That's... quite a lot of pumpkins.\n\nI think our farmer friend should take them back to Hammerfall. Horde reinforcements should be there by now.", objectives = "Recover 4 Prized Pumpkins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90886] = { id = 90886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Laid Plans of Kobolds and Ogres", description = "The kobolds and ogres here seem to be carrying some sort of plan for their attack.\n\nI don't think they're particularly well written, so I'll need several of them to figure out what the ogres are planning.", progress = "Did you recover the plans? They should be on most of the foes within the farm.", completion = "Just as I thought.\n\nI can barely read any of this.", objectives = "Collect 7 Poorly Written Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90887] = { id = 90887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmer's Nemesis", description = "Farmer Bruvk mentioned an ogre named Runk was leading the group here.\n\nThese creatures won't leave this place as long as that ogre is commanding them.", progress = "We'll stay here and guard the remaining farmers while you handle Runk.", completion = "This should help disperse the creatures. Without a leader they'll flee when Alliance and Horde reinforcements show up.", objectives = "Slay Runk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90888] = { id = 90888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Stromgarde Keep", description = "The plans you found indicate the ogres are trying to get food to supply a massive attack on Stromgarde Keep!\n\nOr they're trying to use the crops to keep guarding an object named a storm. The translation was loose. \n\nIt's safe to assume our problem is the former. Let's go!", completion = "This looks bad, but it's nothing we can't handle.", objectives = "Travel to Stromgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90889] = { id = 90889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tale of the Echoes of Sai'alyo" }
quests[90892] = { id = 90892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Skies: A Fel of a Time", description = "<The skies are full of residual time energy and demons pouring in from other timelines.\n\nI should help Eternus by cleaning up the skies. The extra bronze energy would be nice too.>", completion = "<The skies are a little clearer now. The infinites might be interested in trading with this extra bronze I've collected.>", objectives = "Collect bronze by flying through 10 Lost Legion demons and 25 Motes of Bronze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90893] = { id = 90893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repelling the Siege", description = "We must do everything possible to stop this siege on Stromgarde. \n\nMake your way into the battle and weaken the ogre forces.\n\nStromgarde should be able to rally if they can gain the upper hand.", completion = "The siege is at an end. We've got their leader cornered.", objectives = "Repel the Ogre Siege outside of Stromgarde keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90895] = { id = 90895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catapult Bombardment", description = "These catapults are relentless. They must be destroyed.\n\nPlace these rune stones at their base. It'll unleash arcane magic to turn the catapults to dust.\n\nI'll take out a few as well as I make my way across the battlefield.", completion = "With the catapults gone the soldiers of Stromgarde should be able to gain the upperhand.", objectives = "Apply Jaina's Runes to 4 Catapults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90896] = { id = 90896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Ogre", description = "The head of the siege is still cowering within the former Horde encampment. \n\nHe managed to hide from Jaina's spell behind several of his cohorts.\n\nYou can have the honors to confront of him. Jaina and I will stay here to ensure any remnants of the siege do not return.\n\nEnd this.", progress = "Defeat Ro'grok and end this siege.", completion = "The siege is over. Arathi Highlands will hopefully return to a somewhat peaceful state now.", objectives = "Slay Ro'grok", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90897] = { id = 90897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Stromgarde", description = "I think we can count ourselves lucky there was no bigger threat here beyond a group of overambitious ogres. \n\nThe same can't be said of other threats that are looming throughout Azeroth.\n\nCome. Let's return to Stromgarde to discuss matters further.", completion = "It's good to see the people here in high spirits.", objectives = "Meet Jaina Proudmoore within Stromgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90898] = { id = 90898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Hammerfall", description = "We're not always so lucky that a plan such as this is ended so swiftly and without a surprise portal or two.\n\nThat being said, more dangers lurk throughout Azeroth. I know you can be of help to some.\n\nLet us return to Hammerfall to see how they're recovering.", completion = "Hammerfall will recover in time and become stronger than it was before.", objectives = "Return to Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90901] = { id = 90901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As A Matter of Artifact", description = "There's more to artifacts than meets the eye, {name}.\n\nSimply using an artifact allows its legend to grow, and as that legend grows, so too does its power.\n\nIn order to unlock the full potential of that power, however, you'll need to focus infinite power into the artifact's traits. As more traits are empowered the artifact's true potential will be unlocked, and its legend will be undeniable.\n\nLet's get started.", progress = "Unlocking the full potential of your artifact will be key to understanding their impact on this timeline.", completion = "As you gather infinite power do not forget to focus it into your artifact.\n\nThe more power you invest, the swifter you will gather more infinite power and grow your artifact's legend--and your own.", objectives = "Unlock artifacts traits using Infinite Power gained from looting Epoch Mementos from any enemy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90907] = { id = 90907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First to Know", progress = "I hope our fair town is treating you well. If you have any concerns at all, bring them to me.", completion = "It is heartening that you trust me with these serious concerns.", objectives = "Inform Lord Antenorian, governor of Tranquillien, of your investigation results.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90910] = { id = 90910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overwhelming Darkness", description = "A dreadful presence calls from the den just to the southeast of here. Many of the dazed ren'dorei you see in camp were overwhelmed by its raw power on a scouting mission.\n\nLet us go together and see if whatever dwells within can be put to use. We cannot afford to spurn power in the fight against Xal'atath.\n\nBefore that: we have little need of Kalgorg. The Voidstorm has made my voidwalker unruly and disobedient. Assist me in sacrificing it. We will need all of the Void energy we can muster.", progress = "Disobedient little...", completion = "Kalgorg descended here, but I won't confront it unprepared.\n\nThat disobedient little monster. It thinks it can simply walk away after two decades?", objectives = "Sacrifice Kalgorg and then meet Lucia Nightbreaker in the Den of Predaxes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90911] = { id = 90911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Next Adventure", objectives = "Choose your next adventure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90914] = { id = 90914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Born Killer", description = "Ah, {name}. I have so enjoyed our time together. I hunger for more. \n\nI wish you knew more of me than my predilection for the taste of mortal suffering. One of my greatest joys is in crafting Void power into various objects and structures. It is my passion--my art.\n\nHere, I would like to show you. First, we will need power. You already know how to get it, of course: kill, kill, kill.", progress = "What an odd feeling. I feel almost... drawn to you. It must be your mesmerizing presence.", completion = "My, what delightfully gruesome success. \n\nI am interested to work together with you. You should know more of our people, and see more of my abilities.", objectives = "Collect 15 Void Essence from monsters around Voidstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90915] = { id = 90915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifice of Aggression", description = "While we domanaar are best known for leading armies and savoring battles, there is more to us. \n\nMany, like myself, enjoy using our mastery over the Void to shape it into the buildings and objects you see around you. \n\nHow do you think Xal'atath learned to create that great tower of hers? She's a quick study. \n\nCome now, and I will show you my work.", progress = "How excellent to spend some time together. You mortals are so very interesting... you most of all.", completion = "Consider this blade my gift to you. We shall work together to make you into a true weapon of destruction.", objectives = "Craft a blade with Decimus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90916] = { id = 90916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek to Destroy", description = "It's no easy thing, intertwining Light and Void together. The result is unstable, so we must continue to temper it. \n\nWe shall quench this blade in the blood of our enemies. \n\nSome domanaar attempt to reclaim and re-power Nexus-Point Xenas. That won't be good for your people. I'll assume you want to stop it. \n\nWhat is it you mortals say? Two birds, one stone?", completion = "These Nexus-Points used to be fonts of power for us domanaar to enjoy, long before Xal'atath overthrew us. \n\nSomeday, they shall be so again.", objectives = "Meet Decimus at Nexus-Point Xenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90917] = { id = 90917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvester of Savagery", description = "The blade hungers! The blood of our enemies will help stabilize and hone our nascent weapon. \n\nYou'll need to drench the blade inside some corpses. So, you'll need to make corpses. \n\n<Decimus's smile grows broader.> \n\nYou're good at that, right?", progress = "The monsters native to this land are fierce and violent. Their bloodlust drew the Void here, so naturally... we feel quite at home here.", completion = "Very good. \n\nI understand you mortals fret over things like ecological balance and culling of species. \n\nFear not: the monsters here are as endless as they are brutal.", objectives = "Use the Nascent Blade on corpses in Nexus-Point Xenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90918] = { id = 90918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unforgiven", description = "Since even before our little misadventure, Nexus-Point Xenas has always been the weakest link. The beasts here are stubborn and powerful, always pushing deeper and deeper in. \n\nSome domanaar seek to reclaim the Nexus-Point. They are known to me: weaklings, fighting for scraps. Let's ensure they fail.", completion = "Ah, how quaint, to catch up with old enemies. \n\nWe domanaar once had intricate structures of power. Each domanaar fights for their own sake alone, but it is often advantageous to align oneself with others. Temporarily, of course. \n\nThe most powerful among us were the High Lords. When Xal'atath arrived... she made an example of them all. The spectacle was so moving, it drew not only fear but something closer to loyalty from us domanaar. \n\nSome, though not all.", objectives = "Slay Noxian, Averus, and Tenebre around Nexus-Point Xenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90919] = { id = 90919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fiend That Failed", description = "The blade squirms. It is ready for its next transformation.\n\nThere is only the leader, Vortensiun, left. \n\nHe is known to me. Once, we formed a pact together to defeat a rival. When the time came for him to betray me, he did so clumsily. \n\nI let him live, so I could savor the taste of his regret. \n\nI wonder how well that pain has marinated by now? Let's find out. When the blade is tempered in his essence, it shall grow new power.", completion = "Pay no mind to Vortensiun's comment about food. \n\nWe are becoming good friends, are we not?", objectives = "Slay Vortensiun in Nexus-Point Xenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90920] = { id = 90920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warmth for the Soul", description = "Enjoying the view? \n\nThe blade is stronger now, but it is not yet complete. A weapon worthy of you deserves nothing less than perfection. \n\nBut let us relax for a moment. I understand you mortals enjoy a... casual exchange of conversation to get to know each other better.\n\nI am familiar with the concept, but am curious to see it in action. Indulge me?", completion = "Fascinating, how freely you give up delicate information about yourself.\n\nI choose to believe you would not lie to me, of course. We are friends now, you and I. Such a mortal concept intrigues me.", objectives = "Enjoy a pleasant conversation with Decimus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90922] = { id = 90922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Wake", description = "<The shade flickers. You can barely make out its whisper.>\n\nYou... left me... to die...\n\n<Its arm reaches toward you, then dissipates. Somehow, the presence is a familiar one. You feel that you know this spirit. \n\nYou see more flickers in the distance. What are these shades?>", progress = "Such a strange and terrible place. Fear not--if you wish to converse more to settle your nerves... I am here for you.", completion = "I'm terribly sorry you had to go through that. The words of these spirits have upset you, correct?\n\n<Decimus peers at you.>", objectives = "Dispel spirits in the Gnawing Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90923] = { id = 90923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shepherd of Fear", description = "Our journey continues... one final battlefield. There are vicious beasts aplenty here. Their Void shall fuel the blade even more.\n\nAnd the blade's newfound power shall draw their Void into itself by mere proximity!\n\nThough, this place is different. You may find things you don't expect.\n\nKeep an eye out.", progress = "Don't get distracted, now. This will all be worth it when you have a mighty weapon to hold.", completion = "At long last...", objectives = "Slay monsters and gather Void Essence in the Gnawing Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90924] = { id = 90924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wicked End", description = "The time has come. The final step. \n\n<Decimus pauses, savoring something.>\n\nLet us create the greatest weapon your kind has ever seen.", completion = "The blade, as promised. See? I never meant to keep it for myself. I will even shape it into whichever form suits you best.\n\nThe taste of your suffering was all I desired.", objectives = "Complete the forging of the blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90938] = { id = 90938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Skip Through the Void", description = "Fleshling, do you know about Untethered Space? I am sure you know someone who has encountered it. \n \nPreviously we assumed that only beings of energy such as those from K'aresh could Phase Dive. Since the Harbinger's return, she has created a means for solid creatures to become energy using Reshii Wraps.\n \nMy name is Hashim, and I have some Reshii Wraps in my possession. We are in desperate need of adventurers powerful enough to brave the lucrative depths of Untethered Space.", completion = "I can provide you with everything you need to explore Untethered Space.", objectives = "Meet Hashim at Overlook Zo'Shuul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90943] = { id = 90943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormarion Assault" }
quests[90957] = { id = 90957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Initiation Day", description = "{name}, today is when you find your proper place among the haranir.\n\nRoot Tender Dalnir will guide you. His path is one of tradition and humility, so don't expect excitement. By the end of the day, you will make your mark in the Den of Remembrance. The story you begin now will build on those that came before, like the roots themselves, growing the foundations of Harandar.\n\nDalnir was clearing invasive drifters from the roots. Before you go to him, aid Dalnir by removing some of the pests yourself.", completion = "The time has come to take your place among our people, and give up childish adventures. Follow my guidance and Aln'hara bless this day.\n\nRemember, our traditions show us the way.", objectives = "Elder Hagar is asking you to kill 6 Invasive drifters from around the roots of Teldrassil, and then meet with Root Tender Dalnir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90958] = { id = 90958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roots Above All", description = "Some say the great trees grow, and Harandar will remain even if we do not tend them. Our traditions say, it does not matter. We remain here to protect, tend and serve. We do this with dedication and humility.\n\nKeeping the environment around the roots clean and free of pests reflects upon this duty. Return to me once you are done. You will represent our ways well, {name}.", progress = "Have you performed the tasks that I have asked for?", completion = "Is that an outsider's gear? You were aiding Orweyna with these--distractions, instead of your duties. How will you maintain our traditions if you can not follow my guidance through the ceremony?\n\nI will speak to Elder Hagar. Remember the importance of this day and your duty.", objectives = "Root Tender Dalnir wants you to pull weeds, remove mud skippers and invasive fungi from the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90959] = { id = 90959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traditional Duties", description = "Dalnir has a point about the ceremony, but we should not focus too narrowly. I still hold the values of our people, but sometimes we must look beyond.\n\nDo not worry. You should be focusing on the ceremony. I will search for the outsiders later.\n\nI am sure you could join me once the initiation ceremony is done.", completion = "The outsider told us of your actions. \n\nYou must understand, {name}, though it was courageous, it was dangerous, even for you.\n\nI know Dalnir is furious, but Hagar understands your desire to help.", objectives = "An inner voice is telling you to search for the outsider in Har'mara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90960] = { id = 90960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Story, My Legacy", description = "{name}, the final part of the ceremony is ahead of you, though you've put it at risk with your digressions.\n\nThe first mural will show you a vision of your true self, the one that resonates from within you.\n\nThe second mural will show you a vision of where you are needed.\n\nThe third mural, tradition tells us, breaks the barrier between us and the Goddess herself.\n\nThe ceremony will conclude with you painting your story in the Den.", progress = "Take your time, {name}. The ceremony is not about how fast you do it, but about what you learn from it.", completion = "In all my years of initiations, this has to be a first. It seems that the Goddess herself has noticed you.\n\nI am sensing a mysterious and bountiful journey ahead of you.", objectives = "Elder Hagar asked you to commune with the three murals, and then paint your own story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90961] = { id = 90961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a New Land", description = "{name}, I see you now for who you are. You are dedicated not just to our people, but to the world.\n\nThe goddess has acknowledged you as well, and I can not recall such an event -- not even Orweyna's ceremony was so eventful.\n\nThis is where your story begins. It is time for you to take the first steps of your journey.", completion = "So you are {name}? \n\nI never thought a {race} would show up in the city. With that, Your actions precede you. \n\nI have arranged some basic gear for you. It is the least I can do for saving one of us.", objectives = "With the conclusion of the ceremony, it is now time to start your journey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90962] = { id = 90962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormarion Assault" }
quests[90963] = { id = 90963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caves of the Cleft", description = "Good work freeing the captured rutaani. With the seeds you recovered, I can try to carry on Ru'gar's work.\n\nI did some scouting and gathering while you were keeping the fungarians distracted, and could use your help with another task. Meet me at the cave northeast of here.", completion = "This seems to be a safe location from which to plan our next moves, and one of the plants Ru'gar mentioned to me grows in this area as well.", objectives = "Meet Ney'leia near the northeastern cave in Fungal Cleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90968] = { id = 90968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanic Rumblings", description = "Rumors are abuzz of titan forces being sighted around Khaz Algar. Brann has asked Dagran Thaurissan II for assistance in looking into these rumors.", completion = "If these rumors are true, we must investigate.", objectives = "Seek out Dagran Thaurissan II at the Delver's Headquarters in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90969] = { id = 90969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titan Consoles", description = "Adventurer, the rumors are true. I've seen the titan forces and they are nae friendly. We must try tae discover why they are emergin' now and try and stop 'em from doin' too much damage.\n\nConfront and stop these renegade constructs. To help ye, I've procured some Titan Consoles. I was able to set them up in the affected areas. I can use them to communicate with ye in the field. I am thinkin' we can use them to counter these titan forces as well.", completion = "{name}, these consoles are bein' overloaded by the titan's presence. If we can defeat them and secure titan discs, I think we can use 'em to empower the console to grant ye boons within the space. The boons can aid you in pushing back these rogue titan constructs.", objectives = "Seek out one of Dagran's Titan Consoles in an Overcharged Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90970] = { id = 90970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titan Disc-Count", description = "We need tae secure more titan discs. Venture deeper into this area, seek out the Titan Constructs, and defeat them. Ye should find disc shards. This console can reassemble them and access their data. \n\nMake sure tae search for any treasure rooms as well. The constructs appear to be assistin' the local denizens. Some of those locals might've secured additional titan discs with their other treasures.", progress = "Adventurer? Is that you?", completion = "Did ye find the shards? While ye were away, I remembered I'd found some on my visit to that location. Ye should find them in a pouch I hid next to the console.", objectives = "Secure Titan Disc Shards and dispatch Titan Constructs within the delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90971] = { id = 90971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overcharged Console", description = "With the shards ye found, we can use the console tae restore the titan discs and use them to access powerful boons. \n\nUse the console's disc repair feature to create a titan disc, then use that disc to select a starting node in the overcharge console's interface.", progress = "Did it work?", completion = "My remote console shows that there was a change. The overcharged console is funnelin' excess energy to a new node. This should grant ye that node's power when venturin' intae other areas where the titan constructs have emerged.\n\nWe'll use the titan force's own energy against 'em!", objectives = "Restore a Titan Disc and then spend it to unlock one of the starting nodes in the Overcharged Console Tech Tree.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90972] = { id = 90972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Common Cause", description = "{name}! I heard you were here on K'aresh. Good. I need help.\n \nMy apprentice Leona has been researching novel means of harnessing the power of the Void. She's approached a Demon Hunter named Adarus to see if the Illidari's methods could offer any insights.\n \nTo be honest, I'm not sure I trust Adarus. He's not... studious. Unlike Leona.\n \nLeona was just going to observe him as he sought to master the Void. But she's disappeared. Please find her. Talk with Adarus--he knows something.", progress = "Have you spoken to Adarus yet, {name}? It's clear that the Illidari's apotheosis has stripped them of their manners.", completion = "Adarus sent you? \n\nHis lack of faith in my abilities and desire to delegate speak volumes.", objectives = "Speak to Adarus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90995] = { id = 90995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of The Fel Hammer", description = "Oh wait! Of course, right when I send you off I remember the most important thing!\n\nThe you-of-this-timeline made a critical choice for the future of all demon hunters. The follower they chose to be their personal champion created two diverging timelines for the fate of the Illidari.\n\nYou will need to choose which of these diverging timelines to explore. What rings true to you?", progress = "Have you made a choice?", completion = "Very well, we will study this version of the timeline. Let us see what the Illidari hold in their future--err, past.", objectives = "Choose your personal champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
